        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "sumViews",
    "type": "core.action.script",
    "typeVersion": "1.1",
    "display": {
      "label": "Sum Views"
    },
    "inputs": {
      "script": "const items = $vars.filterHighViews.output;\nconst total = items.reduce((sum, item) => sum + item.views, 0);\nreturn { total };"
    },
    "outputs": {
      "output": {
        "type": "any",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "successEnd",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {
      "label": "Success"
    },
    "inputs": {},
    "outputs": {
      "result": {
        "source": "=js:$vars.sumViews.output.total"
      }
    }
  },
  {
    "id": "errorEnd",
